# Main Shiny page: navigator, import/edit worksheet, analysis options, results,
# graphs, layouts, project information and exports. Input IDs form the contract
# with app.R and the server includes; conditional panels only control visibility.
# Detailed option and result components are built by the sourced UI helpers.
source("R/options_ui.R", local = TRUE)
source("R/results_ui.R", local = TRUE)
source("R/nested_ui.R", local = TRUE)
ui <- fluidPage(
  theme = bslib::bs_theme(version = 5, bg = "#EDF1F5", fg = "#25364A", primary = "#2467AE", base_font = "system-ui"),
  tags$head(tags$link(rel = "stylesheet", type = "text/css", href = paste0("style.css?v=", unname(tools::md5sum("www/style.css")))), tags$script(src = paste0("worksheet.js?v=", unname(tools::md5sum("www/worksheet.js"))))),
  div(class = "topbar",
    div(class = "brand", span(class = "brand-icon", "L"), "LabStats"),
    div(class = "workspace-status", uiOutput("status")),
    tags$details(class = "project-menu", tags$summary("Project"),
      div(class = "project-menu-content",
        actionButton("project_details", "Project information", class = "project-menu-action"),
        downloadButton("download_project", "Save project", class = "project-menu-action"),
        fileInput("project_file", "Open project", accept = ".json"),
        p(class = "hint", "Saved projects include your tables, analyses, graphs, layouts and notes.")))),
  fluidRow(
    class = "workspace-row",
    column(3, div(class = "panel-card controls",
      h3("Project navigator"),
      textInput("project_search", NULL, placeholder = "Search tables, results and graphs\u2026"),
      div(class = "project-browser", uiOutput("project_tree")),
      tags$details(open = "open", tags$summary("Family"), uiOutput("family_tree"))
    )),
    column(9,
      div(class = "panel-card main-panel", tabsetPanel(id = "tabs", selected = "data",
        tabPanel("Data", value = "data", div(class = "tab-body",
          tags$details(open = "open", tags$summary("Data setup"),
            fluidRow(
              column(6, radioButtons("table_type", "Table type", c("Column" = "column", "XY" = "xy", "Linear mixed analysis" = "nested", "Other analyses" = "other"), inline = TRUE)),
              column(6, selectInput("source", "Data source", c("Saved project table" = "workspace", "Example table" = "demo", "New blank table" = "blank", "Paste from spreadsheet" = "paste", "Import CSV / Excel" = "upload"), selected = "demo"))),
            conditionalPanel("input.source == 'demo'", uiOutput("demo_ui")),
            conditionalPanel("input.source == 'blank'", fluidRow(
              column(6, numericInput("blank_rows", "Rows", 8, min = 3, max = 100)),
              column(6, conditionalPanel("input.table_type != 'xy'", numericInput("blank_groups", "Group columns", 3, min = 2, max = 12))))),
            fluidRow(
              column(6, selectInput("decimal", "Decimal mark", c("Period" = ".", "Comma" = ","))),
              column(6, conditionalPanel("input.table_type != 'xy' && input.table_type != 'nested'", selectInput("layout", "Table layout", c("Column: one group per column" = "wide", "Long: one observation per row" = "long"))))),
            conditionalPanel("input.table_type != 'xy' && input.table_type != 'nested' && input.layout == 'wide'", uiOutput("wide_ui"), p(class = "hint", "For matched data, each row is one subject. Leave missing observations blank."))),
          conditionalPanel("input.source == 'upload'", div(class = "import-panel",
            h3("Import data tables"),
            p(class = "hint", "Choose one or more CSV, TSV, or Excel files (25 MB total per selection). Select a file below to work on it. Use column headers in the first row; leave missing measurements blank."),
            fluidRow(column(8, fileInput("file", "Choose data files", multiple = TRUE, accept = c(".csv", ".tsv", ".txt", ".xlsx", ".xls"))),
              column(4, selectInput("separator", "Text delimiter", c("Comma" = ",", "Tab" = "\t", "Semicolon" = ";")))),
            uiOutput("uploaded_file_ui"), uiOutput("sheet_ui"))),
          fluidRow(column(7, textInput("table_name", "Table name", "Table 1")), column(5, div(class = "download-row", actionButton("save_table", "Save table"), actionButton("copy_table", "Duplicate table")))),
          div(class = "sheet-heading", div(h3(textOutput("sheet_title", inline = TRUE)), textOutput("data_info")), downloadButton("download_data", "Export analysis CSV")),
          conditionalPanel("input.source == 'paste'", textAreaInput("paste_text", "Paste a table including column headers", "", rows = 6, placeholder = "Control\tTreatment\n10.1\t12.4\n9.8\t13.2"), actionButton("apply_paste", "Use pasted table", class = "btn-primary")),
          p(class = "hint", "Click a cell to edit it. Tab moves across cells. Changes are saved when you leave a cell. The first 100 rows are editable; all rows are analyzed."),
          div(class = "table-scroll worksheet-wrap", uiOutput("worksheet")),
          tags$details(tags$summary("Transform / normalize to a baseline"), p("Transform each subject row into a new table. Original measurements remain in their source table."),
            selectInput("transform_operation", "Transformation", c("Ratio to row baseline" = "ratio", "Percent of row baseline" = "percent", "Change from row baseline" = "change", "Percent change from row baseline" = "percent_change", "Natural logarithm" = "log")),
            uiOutput("baseline_ui"), textInput("derived_name", "New table name", "Normalized table"), actionButton("transform_table", "Create transformed table")),
          tags$details(tags$summary("View the mapped analysis data"), div(class = "table-scroll", tableOutput("preview"))),
          div(class = "method-note", h4("Table conventions"), uiOutput("table_help")))),
        tabPanel("Analysis", value = "options", div(class = "tab-body",
          div(class = "analysis-heading", h3("Analysis setup"), actionButton("run", "Run analysis", class = "btn-primary")),
          conditionalPanel("input.table_type == 'column'",
            selectInput("family", "Analysis family", c("Three or more groups / conditions" = "many", "Two groups / conditions" = "two", "One sample versus a value" = "one", "Multiple t-tests" = "multiple_t", "Descriptive statistics" = "summary", "Normality & lognormality" = "normality", "Identify outliers (ROUT)" = "outliers"))),
          selectInput("method", "Analysis", design_methods(), selected = "welch_anova"),
          div(class = "analysis-choice", textOutput("method_help")),
          conditionalPanel("['multiple_t','log_multiple_t'].includes(input.method)",
            selectInput("t_test_mode", "Multiple t-test workflow", c("One test per marker or time point" = "endpoints", "Pairs of data columns" = "columns")),
            conditionalPanel("input.t_test_mode == 'endpoints'", p(class = "hint", "Use long-format data with a marker/time-point column, a group column and a numeric response. Each marker is a separate test of the same two groups."))),
          uiOutput("mapping"),
          tags$details(tags$summary("Other analysis parameters"),
            conditionalPanel("input.method == 'outliers'", selectInput("rout_q", "ROUT false discovery rate Q", c("0.1%" = .001, "1%" = .01, "5%" = .05, "10%" = .1))),
            conditionalPanel("input.method == 'dose'", selectInput("direction", "Curve direction", c("Decreasing (inhibition)" = "decreasing", "Increasing (stimulation)" = "increasing")))),
          p(class = "hint", "Choose assumptions from your study and diagnostics. Results update when you click Run analysis."),
          conditionalPanel("input.table_type != 'nested'", analysis_options_ui()), conditionalPanel("input.table_type == 'nested'", nested_options_ui()))),
        tabPanel("Results", value = "results", div(class = "tab-body", uiOutput("results_header"),
          tags$details(class = "result-management", tags$summary("Analysis name and calculation notes"),
            textInput("analysis_name", "Saved analysis name", ""), actionButton("rename_analysis", "Rename analysis"), uiOutput("notes")),
          uiOutput("cleaned_action"),
          uiOutput("results_tables"), uiOutput("nested_report_view"),
          tags$details(class = "result-exports", tags$summary("Export results and R code"),
            p("Download result tables, a report, or a standalone R script containing the analysis data and settings."),
            div(class = "download-row", downloadButton("download_script", "Reproducible R script"), downloadButton("download_report", "Analysis report"), downloadButton("download_session", "R session details")),
            uiOutput("nested_exports"),
            selectInput("export_table", "Result table", choices = character()), downloadButton("download_table", "Export table CSV"),
            tags$details(tags$summary("Analysis settings"), verbatimTextOutput("settings"))))),
        tabPanel("Graphs", value = "figure", div(class = "tab-body",
          fluidRow(column(6, selectInput("graph_kind", "Graph type", graph_kinds)), column(6, textInput("graph_name", "Saved graph name", ""))),
          actionButton("save_graph", "Save graph"),
          conditionalPanel("input.table_type != 'nested'", tags$details(tags$summary("Graph settings"),
          fluidRow(column(4, selectInput("plot_style", "Column graph", c("Points + mean" = "points", "Box + points" = "box", "Violin + points" = "violin"))),
            column(4, selectInput("error_style", "Mean error bars", c("Confidence interval" = "ci", "Standard deviation" = "sd", "Standard error" = "sem", "None" = "none"))),
            column(4, textInput("plot_title", "Graph title", ""))),
          fluidRow(column(6, textInput("x_label", "X-axis title (optional)", "")), column(6, textInput("y_label", "Y-axis title (optional)", ""))),
          tags$details(tags$summary("Format symbols, lines and axes"), fluidRow(
            column(4, selectInput("palette_name", "Colors", c("Prism colors" = "prism", "LabStats colors" = "color", "Monochrome" = "mono")), selectInput("symbol", "Symbol", c("Filled circle" = 16, "Open circle" = 1, "Square" = 15, "Triangle" = 17))),
            column(4, numericInput("point_size", "Symbol size", 2.6, min = 1, max = 6, step = .2), selectInput("legend", "Legend", c("Bottom" = "bottom", "Right" = "right", "Hidden" = "none"))),
            column(4, selectInput("x_angle", "X label angle", c("Horizontal" = 0, "45 degrees" = 45, "Vertical" = 90)), checkboxInput("connect", "Connect matched subjects", TRUE), checkboxInput("varied_symbols", "Different symbol per column", FALSE), checkboxInput("show_stars", "Show test p-value and stars", FALSE)))))),
          conditionalPanel("input.graph_kind != 'publication'", plotOutput("figure", height = "430px")),
          conditionalPanel("input.graph_kind == 'publication'", imageOutput("publication_preview", height = "auto")),
          div(class = "download-row", downloadButton("download_png", "PNG"), downloadButton("download_svg", "SVG")),
          conditionalPanel("input.table_type == 'nested'", p(class = "hint", "Linear mixed analysis figures use the Figures tab in Analysis. Select Publication SuperPlot for the final-sized panel, key and comparison strip. SVG / PDF / EPS at the configured size are in the download bundle.")),
          tags$details(tags$summary("Assumption diagnostics"), h4("Model diagnostics"), uiOutput("diagnostic_help"), plotOutput("diagnostics", height = "260px"),
          h4("Normality diagnostics"), p(class = "hint", "Shapiro-Wilk results are in the Results sheet. QQ plots show group values, within-subject differences, or model residuals as appropriate. Normality diagnostics do not establish independence or select a test."), plotOutput("normality_figure", height = "340px")))),
        tabPanel("Layouts", value = "layouts", div(class = "tab-body", h3("Arrange saved graphs"),
          textInput("layout_name", "Layout name", "Figure layout"), selectInput("layout_graphs", "Saved graphs", choices = character(), multiple = TRUE),
          fluidRow(column(6, selectInput("layout_mode", "Arrangement", c("Separate panels" = "grid", "Overlay compatible data graphs" = "overlay"))), column(6, numericInput("layout_columns", "Panel columns", 2, min = 1, max = 6))),
          actionButton("save_layout", "Save layout"), plotOutput("layout_figure", height = "600px"),
          div(class = "download-row", downloadButton("download_layout_png", "Layout PNG"), downloadButton("download_layout_svg", "Layout SVG"), downloadButton("download_layout_pdf", "Layout PDF"))))
      ))
    )
  )
)
